#define _GNU_SOURCE
#include <sys/stat.h>
#include <fcntl.h>
#include <stdio.h>
#include <errno.h>
#include <string.h>
#include <unistd.h>

int main(void) {
    struct statx stx;
    const char *path = "/etc/hostname";
    int ret;

    // Request all basic stats and creation time (Btime)
    unsigned int mask = STATX_BASIC_STATS | STATX_BTIME;

    // Retrieve status relative to the current working directory (AT_FDCWD)
    // Do not follow symbolic links (AT_SYMLINK_NOFOLLOW)
    ret = statx(AT_FDCWD, path, AT_SYMLINK_NOFOLLOW, mask, &stx);

    if (ret == -1) {
        fprintf(stderr, "statx failed for %s: %s\n", path, strerror(errno));
        return 1;
    }

    printf("Status retrieved for: %s\n", path);
    printf("------------------------\n");

    // Check if the size field was successfully filled
    if (stx.stx_mask & STATX_SIZE) {
        printf("File Size: %lu bytes\n", (unsigned long)stx.stx_size);
    } else {
        printf("File Size: N/A (Field not supported/filled)\n");
    }

    // Check if Btime (creation time) was filled
    if (stx.stx_mask & STATX_BTIME) {
        printf("Creation Time (Btime): %lu seconds\n", 
               (unsigned long)stx.stx_btime.tv_sec);
    } else {
        printf("Creation Time (Btime): Not available\n");
    }

    return 0;
}
